/** Synthetic in-memory OCR demo. No external requests and no real file output. */
import type { DemoHandler, DemoJobEvent, DemoJobHandler } from "../demoRegistry";
import demoPage1 from "./assets/ocr-page-1.png?inline";
import demoPage2 from "./assets/ocr-page-2.png?inline";
import demoPage3 from "./assets/ocr-page-3.png?inline";
import type { OcrDocument, OcrDocumentDetail, OcrExtraction, OcrPageData, OcrProject } from "../../ocrTypes";

const PNG_BASE64 = "";
const clone = <T,>(value: T): T => JSON.parse(JSON.stringify(value)) as T;
const now = () => new Date().toISOString();
const projectId = "ocr-demo-general";
let counter = 0;
const id = () => `ocr-demo-${++counter}-${Date.now()}`;
const projects: OcrProject[] = [{
  id: projectId, name: "通用 OCR 演示（不调用外部服务）", createdAt: "2026-10-27T02:00:00Z", updatedAt: "2026-10-27T02:00:00Z",
  prompts: { custom: [{ id: "extract", label: "自定义关注事项与字段", prompt: "这是保存在演示项目的自定义提示词，可直接编辑或恢复默认。请摘录单证中的金额和账号，逐字保留证据，不虚构。只输出完整 JSON：{\"coverage_complete\":true,\"items\":[{\"category\":\"\",\"value\":\"\",\"excerpt\":\"\",\"pages\":\"\"}]}" }] },
}];
const initialText = "通用 OCR 合成演示单证\n本样例仅用于演示，不调用外部 OCR 或 AI 服务。\n发票号码：00123456789012345678\n购买方：演示甲公司\n金额：1000.00 元\n税额：130.00 元\n价税合计：1130.00 元\n借款人资产负债率不得超过65%。";
const makePage = (): OcrPageData => ({
  page: 1, text: initialText, originalText: initialText, revision: 1, status: "completed", warnings: [],
  tables: [{ id: "demo-table-1", title: "单证明细", rows: [["项目", "账号／编号", "金额"], ["演示货款", "00123456789012345678", "1130.00"], ["演示利息", "00000888", "25.00"]] }],
  originalTables: [{ id: "demo-table-1", title: "单证明细", rows: [["项目", "账号／编号", "金额"], ["演示货款", "00123456789012345678", "1130.00"], ["演示利息", "00000888", "25.00"]] }],
});
const documents: OcrDocumentDetail[] = [
  { document: { id: "ocr-demo-voucher", projectId, name: "演示单证（已识别）.png", mimeType: "image/png", totalPages: 1, revision: 1, status: "completed", sha256: "synthetic-demo-source-one" }, pages: [makePage()], extractions: [] },
  { document: { id: "ocr-demo-revised", projectId, name: "演示合同（已校对）.png", mimeType: "image/png", totalPages: 1, revision: 2, status: "needs_review", sha256: "synthetic-demo-source-two" }, pages: [{ ...makePage(), text: `${initialText}\n人工校对备注：已核对扫描件账号前导零。`, revision: 2, status: "needs_review", warnings: ["演示提示：请核对表格合计及原扫描件。"] }], extractions: [{ id: "ocr-demo-stale", scenarioId: "custom", sourceRevision: 1, createdAt: "2026-10-27T02:01:00Z", stale: true, prompts: clone(projects[0].prompts.custom), columns: [{ key: "value", label: "摘录金额" }, { key: "sourcePage", label: "页码" }, { key: "evidence", label: "逐字证据" }], rows: [{ value: "1130.00", sourcePage: "1", evidence: "价税合计：1130.00 元" }] }] },
];
// Three authored synthetic pages make whole-document reading and table navigation reviewable.
const multiPages: OcrPageData[] = [1, 2, 3].map(number => {
  const tables = [1, 2, 3, 4].map(index => ({
    id: `multi-${number}-${index}`, title: `明细表 ${number}-${index}`,
    rows: index === 4 ? [Array.from({length: 12}, (_, col) => `字段 ${col + 1}`), Array.from({length: 12}, (_, col) => `内容 ${col + 1}`)]
      : [["项目", "编号", "金额（元）"], ...[1, 2, 3].map(row => [`演示业务 ${row}`, `00${number}${index}${row}`, "100.00"])],
  }));
  const text = `合成单证 · 第 ${number} 页\n仅用于演示全篇原文及多表格交互，不含真实资料。\n` + tables.map(table => `${table.title}\n${table.rows.map(row => row.join("　")).join("\n")}`).join("\n\n");
  return {page: number, text, originalText: text, tables, originalTables: clone(tables), revision: 1, status: "completed", warnings: []};
});
documents.splice(2, 0, {document: {id: "ocr-demo-multipage", projectId, name: "全篇原文与多表格演示（3页12表）.tiff", mimeType: "image/tiff", totalPages: 3, revision: 3, status: "completed", sha256: "synthetic-three-page-tables"}, pages: multiPages, extractions: []});
// 合成文件队列用于检查三列九格、展开与未扫描状态，不读取本机资料。
for (const [index, name] of ["采购合同", "销售合同", "银行回单", "入库单", "出库单", "对账单", "发票", "借款合同", "其他单证"].entries()) {
  documents.push({
    document: { id: `ocr-demo-queue-${index}`, projectId, name: `演示${name}（待扫描）.png`, mimeType: "image/png", totalPages: 1, revision: 0, status: "pending", sha256: `synthetic-demo-queue-${index}` },
    pages: [], extractions: [],
  });
}
function detail(value: unknown): OcrDocumentDetail {
  const found = documents.find((entry) => entry.document.id === value);
  if (!found) throw new Error("演示文件不存在，请重新选择。");
  return found;
}
function project(value: unknown): OcrProject {
  const found = projects.find((entry) => entry.id === value);
  if (!found) throw new Error("演示项目不存在。");
  return found;
}
const failure = (message: string): never => { throw new Error(message); };

export const handlers: Record<string, DemoHandler> = {
  "ocr.projects": () => ({ projects: clone(projects) }),
  "ocr.config_status": () => ({ ocr: { ready: true, engine: "演示（不调用外部服务）" }, llm: { ready: true, visionReady: true } }),
  "ocr.project_save": (params) => {
    const existing = params.id ? project(params.id) : undefined;
    const saved: OcrProject = { id: existing?.id ?? id(), name: String(params.name ?? existing?.name ?? "演示项目"), prompts: clone((params.prompts ?? existing?.prompts ?? {}) as OcrProject["prompts"]), createdAt: existing?.createdAt ?? now(), updatedAt: now() };
    if (existing) projects.splice(projects.indexOf(existing), 1, saved); else projects.unshift(saved);
    return clone(saved);
  },
  "ocr.project_delete": (params) => {
    const existing = project(params.id); projects.splice(projects.indexOf(existing), 1);
    for (let index = documents.length - 1; index >= 0; index--) if (documents[index].document.projectId === params.id) documents.splice(index, 1);
    return { deleted: true };
  },
  "ocr.documents": (params) => ({ documents: clone(documents.filter((entry) => entry.document.projectId === params.projectId).map((entry) => entry.document)) }),
  "ocr.document": (params) => {
    const result = clone(detail(params.documentId));
    result.extractions.forEach((entry) => { entry.stale = entry.sourceRevision !== result.document.revision; });
    return result;
  },
  "ocr.document_bytes": (params) => { detail(params.documentId); return { mimeType: "image/png", dataBase64: PNG_BASE64 }; },
  "ocr.image_pages": (params) => {
    const found = detail(params.documentId);
    return { pages: found.document.id === "ocr-demo-multipage"
      ? [demoPage1, demoPage2, demoPage3].map((imageBase64, index) => ({page: index + 1, imageBase64}))
      : [{ page: 1, imageBase64: PNG_BASE64 }] };
  },
  "ocr.document_prepare": (params) => {
    const found = detail(params.documentId);
    const totalPages = found.document.id === "ocr-demo-multipage" ? 3 : 1;
    if (Number(params.totalPages) !== totalPages) return failure("演示文件页数不匹配。");
    found.document.totalPages = totalPages; return clone(found.document);
  },
  "ocr.document_import": (params) => {
    project(params.projectId);
    const paths = Array.isArray(params.paths) && params.paths.length ? params.paths : ["演示导入单证.png"];
    const imported: OcrDocument[] = paths.map((path) => {
      const doc: OcrDocument = { id: id(), projectId: String(params.projectId), name: `${String(path).split(/[\\/]/).at(-1)?.replace(/\.[^.]+$/, "") ?? "演示导入单证"}.png`, mimeType: "image/png", totalPages: 1, revision: 0, status: "pending", sha256: "synthetic-import" };
      documents.push({ document: doc, pages: [], extractions: [] }); return doc;
    });
    return { documents: clone(imported), failed: [] };
  },
  "ocr.document_delete": (params) => { const found = detail(params.documentId); documents.splice(documents.indexOf(found), 1); return { deleted: true }; },
  "ocr.page_save": (params) => {
    const found = detail(params.documentId); const page = clone(params.page as OcrPageData);
    const existing = found.pages.find((entry) => entry.page === page.page);
    if (Number(params.expectedRevision) !== (existing?.revision ?? 0)) return failure("页面已被修改，本次结果未覆盖人工修订。");
    page.revision = (existing?.revision ?? 0) + 1;
    page.originalText = existing?.originalText ?? ""; page.originalTables = existing?.originalTables ?? [];
    if (existing) found.pages.splice(found.pages.indexOf(existing), 1, page); else found.pages.push(page);
    found.document.revision++; found.document.status = page.status;
    return clone(page);
  },
  "ocr.extraction_save": (params) => {
    const found = detail(params.documentId);
    if (params.sourceRevision !== found.document.revision) return failure("原文已修改，请基于新版本重新摘录。");
    const result: OcrExtraction = { id: id(), scenarioId: String(params.scenarioId), prompts: clone(params.prompts as OcrExtraction["prompts"]), sourceRevision: Number(params.sourceRevision), rows: clone(params.rows as OcrExtraction["rows"]), columns: clone(params.columns as OcrExtraction["columns"]), createdAt: now(), stale: false };
    found.extractions.unshift(result); return clone(result);
  },
};

function events(message: string, produce: () => unknown, outputPaths: string[] = []): DemoJobEvent[] {
  let result: unknown; let completed = false;
  return [
    { phase: "running", current: 0, total: 1, message: `演示：${message}（不调用外部服务）`, severity: "info", outputPaths: [] },
    { phase: "completed", current: 1, total: 1, message: `演示：${message}完成，未写入真实文件`, severity: "success", outputPaths, get result() { if (!completed) { result = produce(); completed = true; } return result; } },
  ];
}

export const jobHandlers: Record<string, DemoJobHandler> = {
  "ocr.recognize_page": (params) => events("识别扫描页", () => {
    const found = detail(params.documentId); const existing = found.pages.find((entry) => entry.page === Number(params.page));
    if (Number(params.expectedRevision) !== (existing?.revision ?? 0)) return failure("页面版本冲突，演示结果未覆盖人工修订。");
    const source = found.document.id === "ocr-demo-multipage" ? multiPages.find(page => page.page === Number(params.page)) ?? makePage() : makePage();
    const page = { ...clone(source), revision: (existing?.revision ?? 0) + 1, originalText: source.originalText, originalTables: clone(source.tables) };
    if (existing) found.pages.splice(found.pages.indexOf(existing), 1, page); else found.pages.push(page);
    found.document.revision++; found.document.status = "completed"; return clone(page);
  }),
  "ocr.extract": (params) => events("按当前提示词摘录", () => {
    const text = String(params.text ?? ""); const prompt = String(params.prompt ?? "");
    if (/财务契约|line_start/.test(prompt)) {
      const line = Number(text.match(/\[L(\d+)\]借款人资产负债率不得超过65%/)?.[1]);
      return { parsed: { coverage_complete: true, items: line ? [{ title: "资产负债率限制", evidence: [{ line_start: line, line_end: line, role: "obligation" }] }] : [] } };
    }
    const evidence = text.includes("价税合计：1130.00 元") ? "价税合计：1130.00 元" : "";
    return { parsed: { coverage_complete: true, items: evidence ? [{ category: "演示摘录", value: "1130.00", excerpt: evidence, pages: "1" }] : [] } };
  }),
  "ocr.export": (params) => {
    const selected = documents.filter(document => document.document.projectId === params.projectId && (!Array.isArray(params.documentIds) || params.documentIds.includes(document.document.id)));
    if (!selected.length) return failure("请先选择需要导出的文件。");
    if (!["single_sheet", "per_document", "individual", "combined"].includes(String(params.mode))) return failure("请选择有效的导出方式。");
    const outputDir = String(params.outputDir ?? "C:\\演示数据").replace(/[\\/]$/, "");
    const outputPaths = params.mode === "individual" ? selected.map((document, index) => `${outputDir}\\${index + 1}_${document.document.name.replace(/\.[^.]+$/, "")}_OCR.xlsx`) : [`${outputDir}\\OCR演示结果.xlsx`];
    return events("导出 Excel", () => ({outputPaths, documentCount: selected.length, partial: selected.some(document => document.document.status !== "completed")}), outputPaths);
  },
};
